<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';
import {request} from '@/utils/request';
import {date} from '@/utils/format';
import {usePermissions} from '@/store/modules/permission.store';
const props=defineProps<{shop:any}>(),emit=defineEmits(['close','edit','bind']),permissions=usePermissions();
const details=ref<any>(props.shop),tab=ref('detail'),events=ref<any[]>([]),page=ref(1),total=ref(0),busy=ref(false);
const fingerprint=computed(()=>{
  const value=typeof details.value.fingerprint==='string'?JSON.parse(details.value.fingerprint):details.value.fingerprint||{};
  return {...value,language:value.language==='auto'||value.languageMode==='ip'?'跟随 IP':value.language,timezone:value.timezone==='auto'?'匹配 IP':value.timezone==='__local__'?'本地时区':value.timezone};
});
const actions:Record<string,string>={'shop.create':'创建店铺','shop.edit':'编辑店铺','shop.bind':'绑定／解绑设备','shop.copy':'复制店铺','shop.grant':'授权成员','shop.revoke':'撤销授权','shop.recycle':'回收／恢复店铺','shop.delete':'删除店铺'};
const selectedEvent=ref<any>();
const fields:Record<string,string>={name:'店铺名称',sourceId:'源店铺 ID',deviceId:'网络资源 ID',members:'成员 ID',fields:'复制字段',recycled:'回收状态'};
const eventDetail=computed(()=>selectedEvent.value?JSON.parse(selectedEvent.value.detail):{});
async function loadEvents(){busy.value=true;try{const r=await request(`/environments/${props.shop.id}/events?page=${page.value}`);events.value=r.items;total.value=r.total;}finally{busy.value=false;}}
onMounted(async()=>{details.value={...props.shop,...await request(`/environments/${props.shop.id}`)};});
</script>
<template><el-dialog :model-value="true" title="店铺详情" width="860px" :close-on-click-modal="false" @close="emit('close')"><el-descriptions :column="2"><el-descriptions-item label="店铺名称">{{details.name}}</el-descriptions-item><el-descriptions-item label="所属站点">{{details.platform}}</el-descriptions-item><el-descriptions-item label="网络配置">{{details.deviceName||'未绑定'}} <el-button v-if="permissions.can('shop.edit')&&permissions.can('device.view')" link type="primary" @click="emit('bind')">{{details.deviceId?'更换网络':'网络配置'}}</el-button></el-descriptions-item><el-descriptions-item label="店铺账号">{{details.accountName||'未设置'}} <el-button v-if="permissions.can('shop.edit')" link type="primary" @click="emit('edit')">修改</el-button></el-descriptions-item></el-descriptions><el-tabs v-model="tab" @tab-change="tab==='events'&&loadEvents()"><el-tab-pane label="详细信息" name="detail"><el-descriptions :column="1" border><el-descriptions-item label="授权成员">{{details.grantedNames||'暂无授权成员'}}</el-descriptions-item><el-descriptions-item label="平台地址">{{details.startUrl}}</el-descriptions-item><el-descriptions-item label="连接地址">{{details.deviceHost||'—'}}</el-descriptions-item><el-descriptions-item label="内核版本">{{details.kernelVersion}}</el-descriptions-item><el-descriptions-item label="操作系统">{{fingerprint.os||'Windows'}}</el-descriptions-item><el-descriptions-item label="UA"><span class="break-word">{{fingerprint.userAgent||'按内核版本生成'}}</span></el-descriptions-item><el-descriptions-item label="语言 / 时区">{{fingerprint.language}} / {{fingerprint.timezone}}</el-descriptions-item><el-descriptions-item label="店铺备注">{{details.remark||'—'}}</el-descriptions-item><el-descriptions-item label="创建时间">{{date(details.createdAt)}}</el-descriptions-item><el-descriptions-item label="更新时间">{{date(details.updatedAt)}}</el-descriptions-item></el-descriptions></el-tab-pane><el-tab-pane label="操作日志" name="events"><el-table :data="events" v-loading="busy" height="300"><el-table-column prop="actorName" label="操作人"/><el-table-column label="操作内容"><template #default="{row}">{{actions[row.action]||row.action}}</template></el-table-column><el-table-column label="操作时间" min-width="175"><template #default="{row}">{{date(row.createdAt)}}</template></el-table-column><el-table-column label="操作" width="80"><template #default="{row}"><el-button link type="primary" @click="selectedEvent=row">详情</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" @current-change="loadEvents"/></el-tab-pane></el-tabs></el-dialog><el-dialog :model-value="Boolean(selectedEvent)" title="操作详情" width="520px" append-to-body @close="selectedEvent=undefined"><el-descriptions :column="1" border><el-descriptions-item v-for="(value,key) in eventDetail" :key="key" :label="fields[key]||String(key)">{{Array.isArray(value)?value.join('、'):String(value)}}</el-descriptions-item></el-descriptions></el-dialog></template>
